'use client'

// Generated by SpecForge from "Shop" (1.0.0). Safe to edit.
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { useApi } from '@/lib/api/api-provider'
import type { Page } from '@/lib/api/types'
import type { Product, ProductInput } from './types'

const PATH = '/api/shop/products'
const KEY = ['shop', 'product'] as const

export interface ProductFilters {
  q?: string
  page?: number
  size?: number
  sort?: string
}

const item = (id: number) => `${PATH}/${encodeURIComponent(String(id))}`

export function useProductList(filters: ProductFilters) {
  const api = useApi()
  return useQuery({
    queryKey: [...KEY, filters],
    queryFn: () => api.get<Page<Product>>(PATH, { ...filters }),
    placeholderData: previous => previous,
  })
}

export function useSaveProduct() {
  const api = useApi()
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: ({ id, input }: { id?: number; input: ProductInput }) =>
      id != null ? api.put<Product>(item(id), input) : api.post<Product>(PATH, input),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['shop'] }),
  })
}

export function useDeleteProduct() {
  const api = useApi()
  const queryClient = useQueryClient()
  return useMutation({
    mutationFn: (id: number) => api.delete(item(id)),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['shop'] }),
  })
}
